require_once dirname(__DIR__).'/app/bootstrap.php';require_role('admin');$admin=current_user();$errors=[];
if(is_post()){verify_csrf();$action=(string)($_POST['action']??'');
 if($action==='create'){$data=['name'=>trim((string)($_POST['name']??'')),'username'=>strtolower(trim((string)($_POST['username']??''))),'email'=>strtolower(trim((string)($_POST['email']??''))),'school_name'=>trim((string)($_POST['school_name']??'')),'role'=>(string)($_POST['role']??'teacher'),'password'=>(string)($_POST['password']??'')];if(mb_strlen($data['name'])<3)$errors['name']='Enter the staff member’s full name.';if(!preg_match('/^[a-z0-9._-]{3,40}$/',$data['username']))$errors['username']='Use a valid unique username.';if(!filter_var($data['email'],FILTER_VALIDATE_EMAIL))$errors['email']='Enter a valid email address.';if(!in_array($data['role'],['teacher','admin'],true))$errors['role']='Select a staff role.';if(mb_strlen($data['school_name'])<2)$errors['school_name']='Enter the organisation name.';if(strlen($data['password'])<10||!preg_match('/[A-Z]/',$data['password'])||!preg_match('/[a-z]/',$data['password'])||!preg_match('/\d/',$data['password']))$errors['password']='Use at least 10 characters with uppercase, lowercase and a number.';if(!$errors&&Database::fetch('SELECT id FROM users WHERE LOWER(email)=? OR LOWER(username)=?',[$data['email'],$data['username']]))$errors['account']='That email address or username is already in use.';if(!$errors){$id=Auth::createStaff($data);activity('staff_account_created',['created_user_id'=>$id,'role'=>$data['role']]);flash('success','The staff account was created successfully.');redirect('admin/users.php');}}
 if($action==='update'){$id=request_int('user_id');$role=(string)($_POST['role']??'learner');$status=(string)($_POST['status']??'active');if($id===(int)$admin['id']&&$status!=='active'){flash('error','You cannot disable your own administrator account.');redirect('admin/users.php');}if(!in_array($role,['learner','teacher','admin'],true)||!in_array($status,['active','disabled','pending'],true)){flash('error','The requested role or status is invalid.');redirect('admin/users.php');}Database::query('UPDATE users SET role=?,status=? WHERE id=?',[$role,$status,$id]);activity('user_account_updated',['updated_user_id'=>$id,'role'=>$role,'status'=>$status]);flash('success','The account role and status were updated.');redirect('admin/users.php');}
 if($action==='reset_password'){$id=request_int('user_id');$password=(string)($_POST['new_password']??'');$confirmation=(string)($_POST['new_password_confirmation']??'');if(strlen($password)<10||!preg_match('/[A-Z]/',$password)||!preg_match('/[a-z]/',$password)||!preg_match('/\d/',$password)){flash('error','The new password must contain at least 10 characters with uppercase, lowercase and a number.');redirect('admin/users.php?reset='.$id);}if($password!==$confirmation){flash('error','The password confirmation does not match.');redirect('admin/users.php?reset='.$id);}if(!Database::fetch('SELECT id FROM users WHERE id=?',[$id])){flash('error','The selected account no longer exists.');redirect('admin/users.php');}Database::query('UPDATE users SET password=?,updated_at=CURRENT_TIMESTAMP WHERE id=?',[password_hash($password,PASSWORD_DEFAULT),$id]);Database::query('DELETE FROM login_attempts WHERE identifier IN (SELECT LOWER(email) FROM users WHERE id=?) OR identifier IN (SELECT LOWER(username) FROM users WHERE id=?)',[$id,$id]);activity('user_password_reset',['updated_user_id'=>$id]);flash('success','The account password was reset securely.');redirect('admin/users.php');}
}
